function formCourse(id){const old=id?course(id):null;openModal(old?'Editar curso':'Cadastrar curso','O curso inicia em Rascunho. A ativação exige a etapa de revisão.',input('name','Título', 'text',old?.name,true)+area('description','Descrição',old?.description)+area('objectives','Objetivos',old?.objectives)+input('hours','Carga horária (horas)','number',old?.hours||20,true,'min="1"')+select('modality','Modalidade',['Presencial','Remoto','Híbrido'],old?.modality)+input('languages','Idiomas','text',old?.languages||'Português',true)+input('territories','Territórios','text',old?.territories||'',true)+input('audience','Público-alvo','text',old?.audience||'',true)+input('attendanceMin','Frequência mínima (%)','number',old?.attendanceMin??75,true,'min="0" max="100"')+input('area','Área temática','text',old?.area||''),f=>{const hours=Number(f.hours),attendanceMin=Number(f.attendanceMin);if(hours<1||attendanceMin<0||attendanceMin>100)throw Error('Verifique a carga horária e a frequência mínima.');if(old){if(old.status==='Encerrado')throw Error('Cursos encerrados não podem ser editados.');if(db.certificates.some(x=>x.courseId===old.id)&&hours!==old.hours)throw Error('A carga horária está bloqueada após a emissão de certificados.');Object.assign(old,{...f,hours,attendanceMin});}else db.courses.push({id:nextId('courses'),...f,hours,attendanceMin,status:'Rascunho'});record('Curso',old?'Curso atualizado.':'Curso cadastrado como Rascunho.');navigate('courses');});}
function formTrail(){openModal('Cadastrar trilha','Informe cursos obrigatórios, opcionais e pré-requisitos. Use os identificadores separados por vírgula.',input('name','Nome da trilha','text','',true)+area('description','Descrição')+`<p class="table-note">Cursos disponíveis: ${db.courses.map(c=>`${c.id} — ${escapeHTML(c.name)}`).join(' · ')}</p>`+input('required','IDs dos cursos obrigatórios','text','',true)+input('optional','IDs dos cursos opcionais')+input('dependencies','Pré-requisitos (ex.: 2:1;3:1,2)'),f=>{const parse=s=>String(s||'').split(',').map(Number).filter(Boolean);const required=parse(f.required),optional=parse(f.optional),prerequisites={};if(!required.length||[...required,...optional].some(id=>!course(id)))throw Error('Informe IDs válidos de cursos.');for(const part of f.dependencies.split(';').filter(Boolean)){const [id,refs]=part.split(':');if(!course(Number(id)))throw Error('Curso inválido no pré-requisito.');prerequisites[id]=parse(refs);if(prerequisites[id].some(x=>!course(x)))throw Error('Pré-requisito inválido.');}const visiting=new Set(),done=new Set();const visit=id=>{if(visiting.has(id))throw Error('Não são permitidos ciclos de pré-requisitos.');if(done.has(id))return;visiting.add(id);(prerequisites[id]||[]).forEach(visit);visiting.delete(id);done.add(id);};Object.keys(prerequisites).forEach(visit);db.trails.push({id:nextId('trails'),name:f.name,description:f.description,required,optional,prerequisites});record('Trilha','Trilha cadastrada.');navigate('trails');});}
function formMaterial(){openModal('Cadastrar material didático','Materiais tradicionais precisam de consentimento vigente antes da aprovação.',input('title','Título','text','',true)+select('courseId','Curso',db.courses.map(c=>({value:c.id,label:c.name})))+select('type','Formato',['PDF','MP4','MP3','OGG','JPG','PNG'])+select('origin','Origem',['Institucional','Tradicional'])+area('description','Descrição'),f=>{db.materials.push({id:nextId('materials'),title:f.title,courseId:Number(f.courseId),type:f.type,origin:f.origin,description:f.description,status:'Pendente',consentId:null,version:1});record('Material','Material cadastrado e encaminhado para análise.');notify('Material pendente',f.title);navigate('materials');});}
function formConsent(){const eligible=db.materials.filter(m=>m.origin==='Tradicional');if(!eligible.length)return toast('Cadastre um material de origem tradicional primeiro.');openModal('Registrar consentimento','Informe a autorização da liderança ou representação comunitária.',select('materialId','Material tradicional',eligible.map(m=>({value:m.id,label:m.title})))+input('leader','Representante comunitário','text','',true)+input('date','Data','date',today(),true)+select('method','Forma de consentimento',['Reunião','Documento assinado','Registro oral','Outra'])+input('attachment','Referência do registro (opcional)'),f=>{const c={id:nextId('consents'),materialId:Number(f.materialId),leader:f.leader,date:f.date,method:f.method,attachment:f.attachment,status:'Vigente'};db.consents.push(c);get('materials',c.materialId).consentId=c.id;record('Consentimento','Consentimento registrado (demonstração).');navigate('consents');});}
function formClass(){const active=db.courses.filter(c=>c.status==='Ativo');if(!active.length)return toast('Ative um curso antes de cadastrar a turma.');openModal('Cadastrar turma','Uma turma deve estar vinculada a um curso ativo.',select('courseId','Curso ativo',active.map(c=>({value:c.id,label:c.name})))+input('name','Nome da turma','text','',true)+input('location','Local','text','',true)+input('start','Data inicial','date',today(),true)+input('end','Data final','date',today(),true)+input('capacity','Capacidade','number',20,true,'min="1"')+input('facilitator','Facilitador responsável','text','',true),f=>{if(f.end<f.start)throw Error('A data final deve ser igual ou posterior à inicial.');db.classes.push({id:nextId('classes'),...f,courseId:Number(f.courseId),capacity:Number(f.capacity),meetings:[]});record('Turma','Turma cadastrada.');navigate('classes');});}
function formMeeting(id){const c=classroom(id);openModal('Cadastrar encontro',c.name,input('date','Data','date',today(),true)+input('topic','Tema do encontro','text','',true),f=>{const id=Math.max(0,...db.classes.flatMap(c=>c.meetings.map(m=>m.id)))+1;c.meetings.push({id,...f});record('Encontro','Encontro cadastrado.');navigate('classes');});}
function formEnrollment(){openModal('Inscrever participante','O sistema verifica duplicidade, capacidade e pré-requisitos.',select('personId','Participante',db.people.map(p=>({value:p.id,label:p.name})))+select('classId','Turma',db.classes.filter(c=>course(c.courseId)?.status==='Ativo').map(c=>({value:c.id,label:c.name})))+input('newPerson','Ou cadastrar novo participante (nome)'),f=>{let personId=Number(f.personId);if(f.newPerson.trim()){personId=nextId('people');db.people.push({id:personId,name:f.newPerson.trim()});}const c=classroom(f.classId);if(!c)throw Error('Selecione uma turma válida.');if(countEnrolled(c.id)>=c.capacity)throw Error('Turma sem vagas.');if(enrolled(personId,c.id))throw Error('Este participante já está inscrito nesta turma.');if(!prerequisitesMet(personId,c.courseId))throw Error('O participante ainda não cumpriu os pré-requisitos desta trilha.');db.enrollments.push({id:nextId('enrollments'),personId,classId:c.id,status:'Inscrito'});record('Inscrição','Inscrição realizada.');notify('Nova inscrição',`${fullName(personId)} · ${c.name}`);navigate('enrollments');});}
function meetingOptions(){return db.classes.flatMap(c=>c.meetings.map(m=>({value:m.id,label:`${c.name} · ${date(m.date)} · ${m.topic}`})));}
function formAttendance(id){const old=id?get('attendance',id):null;openModal(old?'Corrigir frequência':'Registrar frequência','Os registros de presença são associados a encontros e participantes.',select('meetingId','Encontro',meetingOptions(),old?.meetingId)+select('personId','Participante',db.people.map(p=>({value:p.id,label:p.name})),old?.personId)+select('present','Presença',[{value:'true',label:'Presente'},{value:'false',label:'Ausente'}],old?String(old.present):'true')+input('reason','Justificativa da correção (se aplicável)'),f=>{const m=db.classes.find(c=>c.meetings.some(x=>x.id===Number(f.meetingId)));if(!m||!enrolled(Number(f.personId),m.id))throw Error('Participante não inscrito na turma deste encontro.');const previous=db.attendance.find(a=>a.personId===Number(f.personId)&&a.meetingId===Number(f.meetingId));const present=f.present==='true';if(previous){previous.revisions.push({present:previous.present,reason:f.reason,date:new Date().toISOString()});previous.present=present;previous.source=online?'Servidor simulado':'Offline simulado';}else db.attendance.push({id:nextId('attendance'),personId:Number(f.personId),meetingId:Number(f.meetingId),present,source:online?'Servidor simulado':'Offline simulado',revisions:[]});record('Frequência','Frequência registrada com histórico de correções.',true);navigate('attendance');});}
function formAssessment(id){const old=id?get('assessments',id):null;openModal(old?'Corrigir avaliação':'Registrar avaliação','Registre o resultado da avaliação de um participante.',select('classId','Turma',db.classes.map(c=>({value:c.id,label:c.name})),old?.classId)+select('personId','Participante',db.people.map(p=>({value:p.id,label:p.name})),old?.personId)+input('title','Descrição da avaliação','text',old?.title||'',true)+select('type','Tipo',['Oral','Prática','Prova','Coletiva','Autoavaliação'],old?.type)+input('result','Resultado (nota de 0 a 10 ou Satisfatório / Não satisfatório)','text',old?.result||'',true),f=>{if(!enrolled(Number(f.personId),Number(f.classId)))throw Error('Participante não inscrito na turma.');const r=f.result.trim(),n=Number(r.replace(',','.'));if(!['Satisfatório','Não satisfatório'].includes(r)&&(!Number.isFinite(n)||n<0||n>10))throw Error('Use nota de 0 a 10 ou conceito Satisfatório / Não satisfatório.');const value=['Satisfatório','Não satisfatório'].includes(r)?r:String(n);if(old)Object.assign(old,{...f,personId:Number(f.personId),classId:Number(f.classId),result:value});else db.assessments.push({id:nextId('assessments'),...f,personId:Number(f.personId),classId:Number(f.classId),result:value,status:'Validada'});record('Avaliação','Avaliação registrada.',true);navigate('assessments');});}
function reportData(id){const c=course(id),classes=db.classes.filter(t=>t.courseId===c.id),enrollments=db.enrollments.filter(e=>classes.some(t=>t.id===e.classId)),active=enrollments.filter(e=>e.status==='Inscrito');return {curso:c.name,turmas:classes.length,inscricoes:active.length,canceladas:enrollments.length-active.length,conclusoes:active.filter(e=>completion(e.personId,e.classId)).length,materiaisInstitucionais:db.materials.filter(m=>m.courseId===c.id&&m.origin==='Institucional').length,materiaisTradicionais:db.materials.filter(m=>m.courseId===c.id&&m.origin==='Tradicional').length};}
function download(text,name,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function handle(action,el){const id=Number(el.dataset.id);switch(action){case 'dismiss-notice':noticeVisible=false;render();break;case 'new-course':formCourse();break;case 'edit-course':formCourse(id);break;case 'go-courses':navigate('courses');break;case 'go-materials':navigate('materials');break;case 'course-detail':navigate('course-detail',id);break;case 'set-course-status':{const c=course(id),s=el.dataset.status;if(c.status==='Em revisão'&&s==='Ativo'&&!confirm('Confirmar aprovação e ativação deste curso na demonstração?'))break;c.status=s;record('Curso',`Situação alterada para ${s}.`);navigate('course-detail',id);break;}case 'new-trail':formTrail();break;case 'new-material':formMaterial();break;case 'new-consent':formConsent();break;case 'new-class':formClass();break;case 'new-meeting':formMeeting(id);break;case 'new-enrollment':formEnrollment();break;case 'new-attendance':formAttendance();break;case 'edit-attendance':formAttendance(id);break;case 'new-assessment':formAssessment();break;case 'edit-assessment':formAssessment(id);break;case 'cancel-enrollment':{const e=get('enrollments',id);if(confirm('Cancelar inscrição? O histórico será mantido.')){e.status='Cancelado';record('Inscrição','Inscrição cancelada; vaga liberada.');navigate('enrollments');}break;}case 'review-material':{const m=get('materials',id);openModal('Analisar material','Aprovação exige consentimento vigente para conteúdos tradicionais.',select('decision','Decisão',['Aprovado','Rejeitado'])+area('reason','Justificativa'),f=>{if(m.origin==='Tradicional'&&!db.consents.some(c=>c.id===m.consentId&&c.status==='Vigente')&&f.decision==='Aprovado')throw Error('É necessário consentimento comunitário vigente.');m.status=f.decision;m.reason=f.reason;record('Material',`Material ${f.decision.toLowerCase()}.`);notify('Decisão sobre material',`${m.title}: ${f.decision}`);navigate('materials');});break;}case 'revoke-consent':{const c=get('consents',id);if(confirm('Revogar este consentimento?')){c.status='Revogado';const m=get('materials',c.materialId);if(m){m.status='Revogado';m.version++;}record('Consentimento','Consentimento revogado. Acesso demonstrativo ao material bloqueado.');navigate('consents');}break;}case 'download-material':toast('Download ilustrativo: nenhum arquivo foi armazenado no dispositivo.');break;case 'show-certificate':{const e=get('enrollments',id),c=classroom(e.classId),courseObj=course(c.courseId);openModal('Certificado demonstrativo','Prévia sem validade institucional.',`<div class="info-box"><h3>${escapeHTML(fullName(e.personId))}</h3><p>Concluiu ${escapeHTML(courseObj.name)} · ${courseObj.hours} horas</p><p>Território: ${escapeHTML(courseObj.territories)}</p><p>Código demonstrativo: ${certificateCode(e.personId,e.classId)}</p></div>`,()=>{},'Fechar','CERTIFICADO');$('#modalSubmit').type='button';$('#modalSubmit').onclick=closeModal;break;}case 'read-notification':get('notifications',id).read=true;render();break;case 'toggle-connection':online=!online;render();break;case 'sync-now':if(!online)toast('Sem conexão simulada. Ative a conexão para sincronizar.');else{db.syncQueue.forEach(q=>q.status='Sincronizado (simulado)');toast('Fila marcada como sincronizada nesta sessão.');render();}break;case 'preview-report':case 'export-csv':case 'print-report':{const selected=Number($('#reportCourse')?.value);if(!selected)return toast('Selecione um curso.');const data=reportData(selected);$('#reportPreview').innerHTML=Object.entries(data).map(([k,v])=>`<p><strong>${escapeHTML(k)}:</strong> ${escapeHTML(v)}</p>`).join('');if(action==='export-csv')download('\ufeff'+Object.entries(data).map(([k,v])=>`"${String(k).replace(/"/g,'""')}";"${String(v).replace(/"/g,'""')}"`).join('\r\n'),'relatorio-sistid-demo.csv','text/csv;charset=utf-8');if(action==='print-report')window.print();break;}default:if(!(window.BT&&window.BT.handle(action,el)))toast('Esta ação não está disponível nesta demonstração.');}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return;}const action=e.target.closest('[data-action]');if(action){handle(action.dataset.action,action);return;}const parent=e.target.closest('[data-submenu]');if(parent){const menu=$(`#submenu-${parent.dataset.submenu}`),open=parent.getAttribute('aria-expanded')==='true';parent.setAttribute('aria-expanded',String(!open));parent.classList.toggle('is-open',!open);menu.hidden=open;return;}if(e.target.closest('[data-external-module]'))toast('Este módulo externo não está implementado no protótipo de Formação.');if(e.target.closest('[data-filter]')){filter=e.target.closest('[data-filter]').dataset.filter;$$('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));$('#coursesGrid').innerHTML=courseCards();}});
